//! Transactional switching of the installation's saved-session protection policy.
use super::*;
use crate::{app_lock::SensitiveAction, state::AppState};
use tauri::Manager;

pub(super) async fn change<R: tauri::Runtime>(
    app: tauri::AppHandle<R>,
    auth: AppState,
    state: SettingsState,
    owner: REDACTED,
    next: AppSettings,
    password: REDACTED,
) -> Result<(), CommandError> {
    if !cfg!(target_os = "macos") && !cfg!(test) {
        return Err(CommandError::InvalidInput("Startup verification is a macOS setting".into()));
    }
    let owner = owner.ok_or_else(|| CommandError::Authorization("Sign in to change startup verification".into()))?;
    let lease = auth.session().capture().map_err(CommandError::Authorization)?;
    if lease.owner() != owner {
        return Err(CommandError::Authorization("account session mismatch".into()));
    }
    let save = state.1.clone().lock_owned().await;
    let (revision, previous) = state.snapshot(&owner)?;
    let mut comparable = next.clone();
    comparable.startup_verification = previous.startup_verification;
    comparable.last_user = previous.last_user.clone();
    if serde_json::to_value(&comparable).unwrap() != serde_json::to_value(&previous).unwrap() {
        return Err(CommandError::InvalidInput("Change startup verification separately from other settings".into()));
    }
    if previous.startup_verification == next.startup_verification { return Ok(()); }
    let proof = SensitiveAction::verify(&auth, &lease, password, "change Mesh-Talk startup verification").await?;
    let ordering = auth.auth_operation.clone().lock_owned().await;
    // The actual worker retains both ordering guards even if the IPC future is dropped.
    tokio::task::spawn_blocking(move || {
        let (_save, _ordering) = (save, ordering);
        proof.checked(|| state.commit_current(&owner, revision, || Ok(())))?;
        let (username, secret) = auth.session().matching(&lease, |info| (
            info.user.login_name().to_owned(), zeroize::Zeroizing::new(info.account_login_password.clone())
        )).map_err(CommandError::Authorization)?;
        let mut next = previous.clone();
        next.startup_verification = comparable.startup_verification;
        // comparable was reset above for comparison; use the requested opposite policy.
        next.startup_verification = !previous.startup_verification;
        let mut global = GlobalSettings::from(&next);
        if previous.stay_signed_in {
            global.last_user = Some(username.clone());
            next.last_user = global.last_user.clone();
        }
        #[cfg(test)]
        let path = state.2.clone().or_else(|| config_store::config_path(&app, SETTINGS_FILE));
        #[cfg(not(test))]
        let path = config_store::config_path(&app, SETTINGS_FILE);
        let path = path.ok_or_else(|| CommandError::Io("No settings directory".into()))?;
        let prepared = config_store::prepare_account_write(&path, &global)?;
        if previous.stay_signed_in && !crate::session_store::save_with_policy(&username, &secret, next.startup_verification) {
            return Err(CommandError::Service("Could not save automatic sign-in credentials; startup verification unchanged".into()));
        }
        // Withdraw convenience credentials before claiming protected mode. Never
        // expose an enabled setting while an unprotected recovery entry remains.
        if next.startup_verification {
            crate::session_store::clear_local(&username).map_err(CommandError::Io)?;
        }
        let result = auth.session().matching(&lease, |_| proof.commit(|| {
            if state.snapshot(&owner)?.0 != revision {
                return Err(CommandError::Authorization("settings superseded".into()));
            }
            prepared.commit()?;
            state.update_for_owner(&owner, next)?;
            Ok(())
        })).map_err(CommandError::Authorization).and_then(|result| result);
        if result.is_err() && !global.startup_verification {
            // A cancelled/retired session cannot leave a newly written local secret.
            crate::session_store::clear_local(&username).map_err(CommandError::Io)?;
        }
        result
    }).await.map_err(|_| CommandError::Service("Startup verification worker stopped".into()))?
}
